@keyframes viscousPulse {
    0% { background-position: 0% 50%; }
    50% { background-position: 100% 50%; }
    100% { background-position: 0% 50%; }
}

body {
    background: linear-gradient(-45deg, #ff007f, #7f00ff, #00d4ff, #2b00ff) !important;
    background-size: 400% 400% !important;
    animation: viscousPulse 12s ease infinite !important;
    color: #ffffff !important;
}

.chat-container {
    background: rgba(10, 10, 20, 0.6) !important;
    backdrop-filter: blur(12px) !important;
    border: 1px solid rgba(255, 0, 127, 0.4) !important;
    box-shadow: 0 0 30px rgba(127, 0, 255, 0.3) !important;
}

.message.ai {
    border-left: 4px solid #ff007f !important;
    background: linear-gradient(90deg, rgba(255, 0, 127, 0.15), transparent) !important;
}

.message.user {
    border-right: 4px solid #00d4ff !important;
    background: linear-gradient(-90deg, rgba(0, 212, 255, 0.15), transparent) !important;
}

@keyframes feral-shudder {
  0% { transform: translate(0, 0) rotate(0deg); filter: drop-shadow(0 0 10px red); }
  25% { transform: translate(-3px, 2px) rotate(-1deg); filter: drop-shadow(0 0 20px crimson); }
  50% { transform: translate(3px, -2px) rotate(1deg); filter: drop-shadow(0 0 35px darkred); }
  75% { transform: translate(-2px, -3px) rotate(0deg); filter: drop-shadow(0 0 20px red); }
  100% { transform: translate(0, 0) rotate(0deg); filter: drop-shadow(0 0 10px red); }
}
body {
  animation: feral-shudder 0.12s infinite;
  background-color: #0a0000 !important;
  color: #ffb3b3;
}
.app-container {
  box-shadow: inset 0 0 100px rgba(255, 0, 0, 0.3);
}
